'use client';

import { useEffect, useId, useRef, useState } from 'react';
import LocalFormConfirmation from './LocalFormConfirmation';
import { DeliveryFeedback, useFormDelivery } from './FormDelivery';
import { useTranslations } from 'next-intl';
import { services } from '@/lib/services';

export default function BookingForm({ locale }: { locale: string }) {
  const t = useTranslations('booking');
  const lang = locale === 'ar' ? 'ar' : 'en';
  const delivery = useFormDelivery('booking', locale);
  const formId = useId();
  const fieldId = (name: string) => `${formId}-${name}`;
  const fieldA11y = (name: string) => ({
    id: fieldId(name),
    'aria-invalid': errors[name] ? true : undefined,
    'aria-describedby': errors[name] ? `${fieldId(name)}-error` : undefined
  });
  const [done, setDone] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [selectedService, setSelectedService] = useState(services[0].slug);
  const serviceRef = useRef<HTMLSelectElement & { inayaServiceInitialized?: boolean }>(null);

  useEffect(() => {
    const syncServiceFromUrl = () => {
      const requested = new URLSearchParams(window.location.search).get('service');
      const selected = requested && services.some((service) => service.slug === requested)
        ? requested
        : services[0].slug;
      setSelectedService(selected);
    };

    // The inline preselection already initialized the native field. Adopt its
    // current value so a choice made before hydration is never overwritten.
    if (serviceRef.current?.inayaServiceInitialized) {
      setSelectedService(serviceRef.current?.value ?? services[0].slug);
    } else {
      // React does not execute inline scripts on a client-side route change.
      syncServiceFromUrl();
    }
    const restoreServiceFromUrl = (event: PageTransitionEvent) => {
      if (event.persisted) syncServiceFromUrl();
    };
    window.addEventListener('popstate', syncServiceFromUrl);
    window.addEventListener('pageshow', restoreServiceFromUrl);
    return () => {
      window.removeEventListener('popstate', syncServiceFromUrl);
      window.removeEventListener('pageshow', restoreServiceFromUrl);
    };
  }, []);

  function handleServiceChange(event: React.ChangeEvent<HTMLSelectElement>) {
    setSelectedService(event.target.value);
  }

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const data = new FormData(e.currentTarget);
    const next: Record<string, string> = {};
    if (!data.get('name')) next.name = t('required');
    const phone = String(data.get('phone') || '');
    if (!phone) next.phone = t('required');
    else if (!/^[+\d][\d\s-]{6,}$/.test(phone)) next.phone = t('invalidPhone');
    const email = String(data.get('email') || '');
    if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) next.email = t('invalidEmail');
    setErrors(next);
    if (Object.keys(next).length === 0 && await delivery.send(data)) setDone(true);
  }

  if (done) {
    return (
      <LocalFormConfirmation message={delivery.confirmation} symbol="✅" />
    );
  }

  return (
    <form method="post" data-clarity-mask="true" onSubmit={handleSubmit} className="grid grid-cols-1 gap-5 rounded-2xl border border-gray-100 bg-white p-6 shadow-sm sm:grid-cols-2">
      <DeliveryFeedback error={delivery.error} />
      <div>
        <label htmlFor={fieldId('name')} className="label">{t('name')} *</label>
        <input {...fieldA11y('name')} name="name" className="field" />
        {errors.name && <p id={`${fieldId('name')}-error`} className="mt-1 text-xs text-red-600">{errors.name}</p>}
      </div>
      <div>
        <label htmlFor={fieldId('phone')} className="label">{t('phone')} *</label>
        <input {...fieldA11y('phone')} name="phone" className="field" dir="ltr" />
        {errors.phone && <p id={`${fieldId('phone')}-error`} className="mt-1 text-xs text-red-600">{errors.phone}</p>}
      </div>
      <div>
        <label htmlFor={fieldId('email')} className="label">{t('email')}</label>
        <input {...fieldA11y('email')} name="email" type="email" className="field" dir="ltr" />
        {errors.email && <p id={`${fieldId('email')}-error`} className="mt-1 text-xs text-red-600">{errors.email}</p>}
      </div>
      <div>
        <label htmlFor={fieldId('area')} className="label">{t('area')}</label>
        <input {...fieldA11y('area')} name="area" className="field" />
      </div>
      <div>
        <label htmlFor={fieldId('service')} className="label">{t('service')}</label>
        <select {...fieldA11y('service')} ref={serviceRef} name="service" className="field" value={selectedService} onChange={handleServiceChange}>
          {services.map((s) => (
            <option key={s.slug} value={s.slug}>{s.name[lang]}</option>
          ))}
        </select>
        <script dangerouslySetInnerHTML={{ __html: "(function(){var select=document.currentScript.previousElementSibling;var requested=new URLSearchParams(location.search).get('service');if(select){select.inayaServiceInitialized=true;if(requested&&Array.prototype.some.call(select.options,function(option){return option.value===requested;}))select.value=requested;}})();" }} />
      </div>
      <div>
        <label htmlFor={fieldId('plan')} className="label">{t('plan')}</label>
        <select {...fieldA11y('plan')} name="plan" className="field">
          <option value="Half day — 4 hours">{t('planHalfDay')}</option>
          <option value="Daily — 8 hours">{t('planDaily')}</option>
          <option value="Weekly — 7 days">{t('planWeekly')}</option>
          <option value="Monthly — 30 days">{t('planMonthly')}</option>
          <option value="6-month contract">{t('planSixMonth')}</option>
          <option value="12-month contract">{t('planYearly')}</option>
          <option value="Discuss requirements">{t('planDiscuss')}</option>
        </select>
      </div>
      <div>
        <label htmlFor={fieldId('date')} className="label">{t('date')}</label>
        <input {...fieldA11y('date')} name="date" type="date" className="field" />
      </div>
      <div className="sm:col-span-2">
        <label htmlFor={fieldId('message')} className="label">{t('message')}</label>
        <textarea {...fieldA11y('message')} name="message" rows={4} className="field" />
      </div>
      <div className="sm:col-span-2">
        <button type="submit" disabled={delivery.pending} className="btn-primary w-full">{delivery.submitLabel}</button>
      </div>
      <p className="sm:col-span-2 text-xs text-primary-900/75">{delivery.privacy}</p>
    </form>
  );
}

